import SwiftUI
struct TransactionEntryView:View{@Environment(\.dismiss)private var dismiss;@StateObject var model:TransactionEntryViewModel
 var body:some View{NavigationStack{Form{Section{TextField("Tutar",text:$model.amount).keyboardType(.decimalPad).font(.largeTitle);Picker("Hesap",selection:$model.accountId){Text("Seçin").tag(nil as UUID?);ForEach(model.accounts){Text($0.name).tag(Optional($0.id))}};if model.needsTarget{Picker("Hedef Hesap",selection:$model.targetAccountId){Text("Seçin").tag(nil as UUID?);ForEach(model.accounts.filter{$0.id != model.accountId}){Text($0.name).tag(Optional($0.id))}}};if model.needsCategory{Picker("Kategori",selection:$model.categoryId){Text("Seçin").tag(nil as UUID?);ForEach(model.visibleCategories){Text($0.name).tag(Optional($0.id))}}};DatePicker("Tarih",selection:$model.date)}Section("Açıklama"){TextField("Başlık",text:$model.title)}Section("İleri Alanlar"){if model.needsContact{Picker("Cari",selection:$model.contactId){Text("Seçin").tag(nil as UUID?);ForEach(model.contacts){Text($0.name).tag(Optional($0.id))}}};Toggle("Vade",isOn:$model.hasDueDate);if model.hasDueDate{DatePicker("Vade",selection:$model.dueDate)};TextField("Not",text:$model.note,axis:.vertical)}if let error=model.error{Text(error).foregroundStyle(.red)}}.navigationTitle(title).toolbar{ToolbarItem(placement:.cancellationAction){Button("Vazgeç"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Kaydet"){Task{await model.save();if model.saved{dismiss()}}}}}.task{await model.load()}}}
 private var title:String{switch model.type{case.income:"Gelir Ekle";case.expense:"Gider Ekle";case.transfer:"Transfer";case.collection:"Tahsilat";case.payment:"Ödeme";default:"Yeni İşlem"}}
}

